		if(!navigator.serviceWorker||!navigator.serviceWorker.controller){
			if(!navigator.serviceWorker)throw new Error('Proxy needs HTTPS or localhost');
			await new Promise(function(res,rej){
				var timeout=setTimeout(function(){rej(new Error('Service worker controller timeout'));},12000);
				navigator.serviceWorker.addEventListener('controllerchange',function(){
					clearTimeout(timeout);res();
				},{once:true});
			});
		}
		var params=new URLSearchParams(EFFECTIVE_LOC.search);
		var wispUrl=params.get('wisp')||'wss://catclass.net/wisp/';
		var transport=new window.LibcurlClient({wisp:wispUrl});await transport.init();
		var controller=new $scramjetController.Controller({serviceworker:navigator.serviceWorker.controller,transport:transport,config:{prefix:BASE_PATH+'~/sj/',scramjetPath:'data:text/javascript;base64,',injectPath:'data:text/javascript;base64,',wasmPath:'data:application/wasm;base64,'}});
		await controller.wait();
		return controller;
	})();

	// Resolved once the frame exists, so the inbound command listener (which
	// can arrive at any time) always has something to act on.
	var resolveFrameReady;
	var frameReadyPromise=new Promise(function(res){resolveFrameReady=res;});

	// Commands FROM the parent shell: back/forward/reload/navigate. No origin
	// check for the same reason as postToParent - this embed is meant to be
	// controlled by any shell, and these actions aren't privileged (the embed
	// already navigates to arbitrary URLs by design).
	window.addEventListener('message',function(e){
		if(!e.data||typeof e.data!=='object'||e.data.type!=='arctic-embed:command')return;
		frameReadyPromise.then(function(frame){
			var action=e.data.action;
			if(action==='back')frame.back();
			else if(action==='forward')frame.forward();
			else if(action==='reload')frame.reload();
			else if(action==='navigate'&&e.data.url)frame.go(e.data.url);
		}).catch(function(){});
	});

	async function main(){
		var target=decodeTargetFromHash();
		if(!target){
			showError('No target URL provided. Use embed#<base64url-encoded-url>');
			postToParent({type:'arctic-embed:error',message:'No target URL provided'});
			return;
		}
		if(!target.startsWith('http'))target='https://'+target;

		var iframeEl=createEl('iframe');
		iframeEl.id='embed-frame';
		iframeEl.style.cssText='position:fixed;inset:0;width:100%;height:100%;border:none;';
		docBody().appendChild(iframeEl);

		try{
			var controller=await controllerPromise;
			var plugins=[];
			if(typeof $scramjetUtils!=='undefined'){
				plugins.push(new $scramjetUtils.HttpCachePlugin());
				plugins.push(new $scramjetUtils.EventHandlerPlugin());
				// Mirrors index.html's tab-title/URL-bar sync, but since this
				// frame is cross-origin from the parent's perspective, direct
				// DOM access isn't possible - bridge it via postMessage instead.
				plugins.push(new $scramjetUtils.UrlWatcherPlugin(function(url){
					postToParent({type:'arctic-embed:urlchange',url:url});
				}));
				// Middle-click inside the proxied page: notify the parent to
				// open a new outer tab, rather than navigating this one.
				plugins.push(new $scramjetUtils.LinkHandlerPlugin(function(url){
					postToParent({type:'arctic-embed:newtab',url:url.href||url});
				}));
				// Top-level navigation attempts escaping the proxy (e.g. OAuth
				// redirect flows): redirect back into a fresh instance of this
				// same file (embed.html or embed.svg, whichever is actually
				// deployed - derived from EFFECTIVE_LOC rather than hardcoded)
				// pointed at the escaped target, same pattern as index.html's
				// own '?goto=' handling, just hash-based here.
				plugins.push(new $scramjetUtils.CatchEscapedLinksPlugin(function(url){
					postToParent({type:'arctic-embed:urlchange',url:url.href});
					var selfFile=EFFECTIVE_LOC.pathname.split('/').pop()||'embed.html';
					return new URL(BASE_PATH+selfFile+'#'+toBase64Url(url.href)+EFFECTIVE_LOC.search,EFFECTIVE_LOC.origin);
				}));
			}
			var frame=await controller.createFrame(iframeEl,{plugins:plugins});
			resolveFrameReady(frame);
			await frame.go(target);
			postToParent({type:'arctic-embed:ready',url:target});
		}catch(err){
			console.error('[embed] Failed to load target:',err);
			showError('Failed to load: '+(err&&err.message||err));
			postToParent({type:'arctic-embed:error',message:err&&err.message||String(err)});
		}
	}

	if(document.readyState==='loading'){
		document.addEventListener('DOMContentLoaded',main);
	}else{
		main();
	}
})();
